source_inventory = []

for dataset in datasets:

    files = discover_source_files(
        config,
        dataset
    )

    if not files:
        raise FileNotFoundError(
            f"No files found for {dataset['dataset_id']}"
        )

    for file in files:

        source_inventory.append({
            "dataset_id": dataset["dataset_id"],
            "file_name": file.name,
            "file_path": file.path,
            "file_size_bytes": file.size,
            "file_format": dataset["source"]["format"]
        })

inventory_df = spark.createDataFrame(source_inventory)

display(inventory_df)

for dataset in datasets:
    for file in discover_source_files(config, dataset):
        df = read_source_file(spark, dataset, file.path)

        nulls = df.agg(*[
            F.count(F.when(F.col(c).isNull(), 1)).alias(c)
            for c in df.columns
        ]).first().asDict()

        print(file.name, {k: v for k, v in nulls.items() if v > 0})

for dataset in datasets:
    expected = load_schema(config, dataset)

    for file in discover_source_files(config, dataset):
        actual = read_source_file(spark, dataset, file.path).schema

        assert actual == expected, f"Schema mismatch: {file.name}"

    print(f"PASS: {dataset['dataset_id']}")
